// Macro toggle jour/nuit avec transition douce pour toutes les scènes - Foundry v13

if (!game.user.isGM) return;

// Vérifier si une transition est déjà en cours
if (game.dayNightTransitionRunning) {
    ui.notifications.warn(game.i18n.localize("FQCARDENGINE.MacroErrorMsgDayNightRunning"));
    return;
}

// Marquer la transition comme en cours
game.dayNightTransitionRunning = true;


// Configuration de la transition
const TRANSITION_STEPS = 200;
const STEP_DELAY = 20; // ms entre chaque étape

// Vérifier l'état actuel de la scène active
const isDay = canvas.scene.darkness === 0;
const startDarkness = isDay ? 0 : 1;
const endDarkness = isDay ? 1 : 0;
const endGlobalLight = !isDay;

ui.notifications.info(game.i18n.localize(isDay
    ? "FQCARDENGINE.MacroMsgDayNightToNight"
    : "FQCARDENGINE.MacroMsgDayNightToDay"));

// Fonction de transition douce
async function smoothTransition() {
    // Phase 1: Transition progressive de l'obscurité
    for (let step = 1; step <= TRANSITION_STEPS; step++) {
        const progress = step / TRANSITION_STEPS;
        const currentDarkness = startDarkness + (endDarkness - startDarkness) * progress;

        // Mettre à jour toutes les scènes
        const updates = [];
        for (let scene of game.scenes) {
            updates.push(scene.update({
                darkness: currentDarkness
            }));
        }
        await Promise.all(updates);

        // Rafraîchir la scène active
        if (canvas.scene) {
            canvas.perception.update({refreshLighting: true});
        }

        await new Promise(resolve => setTimeout(resolve, STEP_DELAY));
    }

    // Phase 2: Ajuster la lumière globale à la fin
    const finalUpdates = [];
    for (let scene of game.scenes) {
        finalUpdates.push(scene.update({
            globalLight: endGlobalLight,
            darkness: endDarkness
        }));
    }
    await Promise.all(finalUpdates);

    // Rafraîchissement final
    if (canvas.scene) {
        canvas.perception.update({
            refreshLighting: true, 
            refreshVision: true,
            initializeLighting: true
        });
    }

    ui.notifications.info(game.i18n.localize(isDay
        ? "FQCARDENGINE.MacroMsgDayNightNight"
        : "FQCARDENGINE.MacroMsgDayNightDay"));
    // Libérer le verrou à la fin
    game.dayNightTransitionRunning = false;
}

// Lancer la transition
smoothTransition().catch(() => {
    // En cas d'erreur, libérer le verrou
    game.dayNightTransitionRunning = false;
});
